    click.echo(f"✓ Valid: 2024-02-29 -> {result}")
except click.BadParameter as e:
    click.echo(f"✗ Failed: {e.message}")

# Test invalid dates
for invalid in ['2024-13-01', '01/02/2024', '2023-02-29']:
    try:
        click.DATE.convert(invalid, None, None)
        click.echo(f"✗ Should have failed: {invalid}")
    except click.BadParameter:
        click.echo(f"✓ Correctly rejected: {invalid}")

